function renderSignals(){$('#inputs').innerHTML=inputPorts().map(c=>`<div class="signal-row"><span>${esc(c.name)}</span><div class="toggle"><button data-input="${esc(c.name)}" data-value="0" class="${(inputs[c.name]??0)===0?'active':''}">0</button><button data-input="${esc(c.name)}" data-value="1" class="one ${(inputs[c.name]??0)===1?'active':''}">1</button></div></div>`).join('')||'<p class="prop-description">입력 포트를 배치하세요.</p>';$('#outputs').innerHTML=outputPorts().map(c=>{const v=result.outputs[c.name];return `<div class="signal-row"><span>${esc(c.name)}</span><span class="output-value"><i class="signal-dot ${v===1?'high':v===0?'low':'unknown'}"></i>${v}</span></div>`;}).join('')||'<p class="prop-description">출력 포트를 배치하세요.</p>';const segments=['A','B','C','D','E','F','G'];if(segments.every(n=>n in result.outputs)){const shapes=['M8,3 H32 L37,8 L32,13 H8 L3,8 Z','M34,14 L39,9 L44,14 V34 L39,39 L34,34 Z','M34,44 L39,39 L44,44 V64 L39,69 L34,64 Z','M8,65 H32 L37,70 L32,75 H8 L3,70 Z','M-4,44 L1,39 L6,44 V64 L1,69 L-4,64 Z','M-4,14 L1,9 L6,14 V34 L1,39 L-4,34 Z','M8,34 H32 L37,39 L32,44 H8 L3,39 Z'];$('#fnd-display').innerHTML=`<svg viewBox="-10 -3 60 85" aria-label="7세그먼트 출력">${shapes.map((s,i)=>`<path d="${s}" fill="${result.outputs[segments[i]]===1?'#7ee4c2':'#344958'}"/>`).join('')}</svg>`;}else $('#fnd-display').innerHTML='';}
