if(mode.startsWith('FIG_')){const kind=mode.slice(4),q=snap(p);if(kind==='Text'){snapshot();circuit.figures||=[];const f={id:'f'+sequence++,kind,x:q[0],y:q[1],text:'텍스트',size:15};circuit.figures.push(f);selection=f.id;commit();setMode('select');}else if(!figureStart)figureStart=q;else{snapshot();circuit.figures||=[];circuit.figures.push({id:'f'+sequence++,kind,x:figureStart[0],y:figureStart[1],x2:q[0],y2:q[1]});figureStart=null;commit();$('#preview').innerHTML='';}return;}const figure=e.target.closest('[data-figure]');if(figure&&mode==='select'){selection=figure.dataset.figure;selectedIds.clear();drag={type:'figure',start:snap(p),original:clone(circuit),moved:false};$('#canvas').setPointerCapture(e.pointerId);refresh();return;}if(mode==='place'||mode==='INPUT'||mode==='OUTPUT'){addPart(snap(p));return;}
