function toggleInput(n,v){inputs[n]=v;time+=10;evaluate(true);refresh();if(time>=settings.maxTime)stop();}
function loadCircuit(c){stop();snapshot();if(c.userLibrary){Object.assign(customLibrary.symbols,c.userLibrary.symbols||{});Object.assign(customLibrary.circuits,c.userLibrary.circuits||{});Object.assign(data.symbols,customLibrary.symbols);Object.assign(data.circuits,customLibrary.circuits);}circuit=clone(c);delete circuit.userLibrary;selection=null;selectedIds.clear();inputs={};stimulusText=c.stimulusText||'';try{stimulus=stimulusText?parseStimulus(stimulusText,inputPorts().map(c=>c.name)):{};}catch{stimulus={};}setMode('select');commit();fit();toast(circuit.name+' 회로를 열었습니다.');}
function stop(){if(running)clearInterval(running);running=null;$('#run-button').innerHTML='▶<span>시뮬레이션</span>';}
function step(){const settings=stimulus.clocks?stimulus:parseStimulus(defaultStimulus(),inputPorts().map(c=>c.name));if(!history.length){inputs=stimulusAt(settings,0,inputs);evaluate(true);}const eventTimes=[...Object.values(settings.events).flat().map(e=>e.time),...Object.values(settings.clocks).map(c=>time<c.start?c.start:c.start+(Math.floor((time-c.start)/c.step)+1)*c.step).filter(t=>t<=settings.maxTime)].filter(t=>t>time);time=Math.min(time+10,settings.maxTime,...eventTimes);inputs=stimulusAt(settings,time,inputs);evaluate(true);refresh();}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function selectedParts(){return circuit.components.filter(c=>selectedIds.has(c.id)||c.id===selection);}
function shapeChange(kind){const parts=selectedParts().filter(c=>c.kind==='GATE');if(!parts.length)return;snapshot();for(const c of parts){const before=pinsFor(c,data);if(kind==='left')c.rotation=((c.rotation||0)+270)%360;else if(kind==='right')c.rotation=((c.rotation||0)+90)%360;else if(kind==='horizontal')c.mirror=!c.mirror;else{c.mirror=!c.mirror;c.rotation=((c.rotation||0)+180)%360;}const after=pinsFor(c,data);for(const w of circuit.wires)for(const idx of [0,w.points.length-1]){const i=before.findIndex(p=>p.point[0]===w.points[idx][0]&&p.point[1]===w.points[idx][1]);if(i>=0){const other=idx===0?w.points[1]:w.points[idx-1],end=after[i].point;if(idx===0)w.points=[end,...route(end,other),...w.points.slice(2)];else w.points=[...w.points.slice(0,-1),...route(other,end)];}}}commit();}
function alignParts(kind){const parts=selectedParts();if(parts.length<2){toast('Shift + 클릭으로 두 부품 이상을 선택하세요.');return;}snapshot();const xs=parts.map(c=>c.x),ys=parts.map(c=>c.y),horizontal=kind==='left'||kind==='right'||kind==='across';if(kind==='across'||kind==='down'){const sorted=parts.sort((a,b)=>horizontal?a.x-b.x:a.y-b.y),lo=horizontal?Math.min(...xs):Math.min(...ys),hi=horizontal?Math.max(...xs):Math.max(...ys);sorted.forEach((c,i)=>{const v=Math.round((lo+(hi-lo)*i/(sorted.length-1))/10)*10;moveComponent(c,horizontal?v:c.x,horizontal?c.y:v);});}else{const v=kind==='left'?Math.min(...xs):kind==='right'?Math.max(...xs):kind==='top'?Math.min(...ys):Math.max(...ys);parts.forEach(c=>moveComponent(c,horizontal?v:c.x,horizontal?c.y:v));}commit();}
function showModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function showExamples(){showModal('원본 실습 회로 열기',`<p class="modal-intro">폴더의 MyLogic 회로 10개를 원본 부품과 배선 좌표로 불러왔습니다. 회로를 클릭하면 편집 도면에 열립니다. 현재 회로는 JSON으로 저장할 수 있습니다.</p><div class="examples-grid">${Object.values(data.circuits).map((c,i)=>`<button class="example-card" data-example="${esc(c.name.toUpperCase())}"><span class="example-num">EXERCISE ${String(i+1).padStart(2,'0')}</span><b>${esc(c.name)}</b><small>${esc(names[c.name.toUpperCase()]||'논리회로 실습')}<br>${c.components.filter(c=>c.kind==='GATE').length} 게이트 · ${c.wires.length} 배선</small></button>`).join('')}</div>`);}
function defaultStimulus(){return '[MyLogic STIMULUS V3.5]\nMAX_TIME 1000;\n'+inputPorts().map((c,i)=>`CLOCK ${c.name} FROM : 0 TO : 1000 STEPSIZE : ${10*2**i} 0 1;`).join('\n')+'\nWATCH '+[...inputPorts(),...outputPorts()].map(c=>c.name).join(' ')+';';}
function showStimulus(){showModal('시뮬레이션 입력 설정',`<p class="modal-intro">CLOCK, GEN, VECTOR, WATCH, MAX_TIME 문법을 사용합니다. GEN 예: GEN A 0@0 1@20 X@80; VECTOR 예: VECTOR Result C S;</p><textarea class="stimulus-editor" id="stimulus-text" spellcheck="false">${esc(stimulusText||defaultStimulus())}</textarea><button class="modal-primary" id="apply-stimulus">적용</button><button class="modal-primary" id="export-stimulus" style="margin-right:8px">STIM.STM 저장</button><div style="clear:both"></div>`);$('#apply-stimulus').onclick=()=>{try{const text=$('#stimulus-text').value;stimulus=parseStimulus(text,inputPorts().map(c=>c.name));stimulusText=text;stop();time=0;inputs=stimulusAt(stimulus,0,{});history=[];state={};clocks={};$('#modal').close();evaluate(true);refresh();persist();toast('입력 패턴을 적용했습니다.');}catch(e){toast(e.message);}};$('#export-stimulus').onclick=()=>download('stim.stm',$('#stimulus-text').value,'text/plain');}
function renderFigure(f){let shape='';const x=Math.min(f.x,f.x2??f.x),y=Math.min(f.y,f.y2??f.y),w=Math.abs((f.x2??f.x)-f.x),h=Math.abs((f.y2??f.y)-f.y);if(f.kind==='Text')shape=`<text x="${f.x}" y="${f.y}" fill="#4d6275" stroke="none" font-size="${f.size||15}" font-family="Consolas">${esc(f.text)}</text>`;else if(f.kind==='Rect')shape=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent"/>`;else if(f.kind==='Circle')shape=`<ellipse cx="${x+w/2}" cy="${y+h/2}" rx="${w/2}" ry="${h/2}" fill="transparent"/>`;else if(f.kind==='Arc')shape=`<path d="${arcPath([f.x,-f.y],[f.x2,-f.y2],[(f.x+f.x2)/2,-Math.min(f.y,f.y2)-Math.abs(f.x2-f.x)/2])}" fill="none"/>`;else shape=`<path d="M${f.x},${f.y} L${f.x2},${f.y2}"/>`;return `<g class="figure-part" data-figure="${esc(f.id)}" stroke="${f.id===selection?'#087c72':'#718295'}" stroke-width="${f.id===selection?2:1}" fill="none">${shape}</g>`;}
function renderFigureProperties(){const f=(circuit.figures||[]).find(f=>f.id===selection);if(!f)return false;$('#properties').innerHTML=`<div class="prop-type">${esc(f.kind)}</div><label class="prop-row">X<input id="fig-x" type="number" value="${f.x}" step="10"></label><label class="prop-row">Y<input id="fig-y" type="number" value="${-f.y}" step="10"></label>${f.kind==='Text'?`<label class="prop-row">문자<input id="fig-text" value="${esc(f.text)}"></label><label class="prop-row">크기<input id="fig-size" type="number" min="5" max="100" value="${f.size||15}"></label>`:''}<div class="prop-actions"><button data-action="delete">삭제</button></div>`;for(const k of ['x','y','text','size'])if($('#fig-'+k))$('#fig-'+k).onchange=e=>{snapshot();const v=k==='text'?e.target.value:Number(e.target.value);if(k==='x'||k==='y'){const delta=(k==='y'?-v:v)-f[k];f[k]+=delta;if(f[k+'2']!==undefined)f[k+'2']+=delta;}else f[k]=v;commit();};return true;}
function createUserSymbol(){showModal('Make Symbol · 심벌 제작',`<p class="modal-intro">현재 회로를 계층 부품으로 저장합니다. 입력과 출력 이름을 그대로 사용합니다. 새 이름을 입력하세요.</p><label class="prop-row">심벌 이름<input id="symbol-name" value="${esc(circuit.name)}" style="width:70%"></label><button class="modal-primary" id="create-symbol">심벌 제작</button><div style="clear:both"></div>`);$('#create-symbol').onclick=()=>{try{const name=$('#symbol-name').value.trim().toUpperCase();if(!/^[A-Z_][A-Z0-9_]*$/.test(name)||data.circuits[name])throw Error('영문으로 시작하는 새 심벌 이름을 입력하세요.');const {symbol,text}=makeSymbol(circuit,name),sub=clone(circuit);sub.name=name;sub.library='User';customLibrary.symbols[symbol.key]=symbol;customLibrary.circuits[name]=sub;data.symbols[symbol.key]=symbol;data.circuits[name]=sub;persist();$('#modal').close();filter='USER';renderLibrary();download(name+'.symbol',text,'text/plain');toast(name+' 심벌을 추가했습니다.');}catch(e){toast(e.message);}};}

